import rawSpecies from "@/data/species.json";
import type { Species } from "@/lib/types";

/**
 * Runtime species data (local JSON, generated by scripts/fetch-pokeapi.mjs).
 * The raw JSON is produced by a normalized build step; cast through `unknown`
 * because JSON module inference is too narrow for the domain types.
 */
export const SPECIES: Species[] = rawSpecies as unknown as Species[];

export function getSpecies(speciesId: string): Species | undefined {
  return SPECIES.find((s) => s.speciesId === speciesId);
}
